<?php require 'config.php'; require_role('student'); $title='Grades'; $u=$_SESSION['user']; $term=selected_term($pdo); $tid=$term?(int)$term['id']:0;
$q=$pdo->prepare("SELECT ar.*,s.code,s.name,s.units FROM academic_records ar JOIN subjects s ON s.id=ar.subject_id WHERE ar.user_id=? AND ar.term_id=? ORDER BY s.code");$q->execute([$u['id'],$tid]);$rows=$q->fetchAll();
function grade_num($g){return is_numeric($g)?(float)$g:null;} $nums=array_filter(array_map(fn($r)=>grade_num($r['grade']),$rows),fn($v)=>$v!==null); $avg=$nums?array_sum($nums)/count($nums):null;
require 'header.php'; ?>
<section class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC</span><h2>Grades</h2><p class="muted">Your recorded grades for <?=e($term['label']??'the selected term')?>.</p></div><a class="btn subtle-btn" href="academic_progress.php">Academic Progress</a></div>
<div class="enrollment-overview"><div><span>Subjects Graded</span><strong><?=count($rows)?></strong></div><div><span>Average</span><strong><?=$avg!==null?number_format($avg,2):'—'?></strong></div><div><span>Academic Term</span><strong><?=e($term['label']??'—')?></strong></div></div>
<?php if(!$rows):?><div class="info-box"><b>No grades posted yet.</b><p>Your professors or administration have not posted grades for this term.</p></div><?php else:?><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Units</th><th>Teacher</th><th>Grade</th><th>Remarks</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b><br><small><?=e($r['name'])?></small></td><td><?=e($r['units'])?></td><td><?=e($r['teacher']?:'—')?></td><td><b><?=e($r['grade'])?></b></td><td><span class="badge approved"><?=e($r['remarks'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'footer.php'; ?>
